use emu_arch_x86::{Flags, RFLAGS, RSP, X86Cpu};
use emu_core::{Cpu, CpuError, Machine};
use emu_interpreter::{Breakpoints, Exit, Stop, run};
use emu_shared::{Address, Permissions};

const CODE_BASE: Address = Address(0x1000);
const STACK_TOP: u64 = 0x8000_0000;
const STACK_SIZE: u64 = 0x10000;
const INSTRUCTION_LIMIT: u64 = 1_000_000;

struct Program {
    name: &'static str,
    code: &'static [u8],
    // (name, value) pairs from the file's `; expect name = value` lines.
    expect: &'static [(&'static str, &'static str)],
}

// Generated by build.rs from asm/*.asm and c/*.c: `PROGRAMS` plus one #[test] per file
// that has expect lines.
include!(concat!(env!("OUT_DIR"), "/programs.rs"));

fn signed(value: u128, size: usize) -> i128 {
    let shift = 128 - size * 8;
    ((value << shift) as i128) >> shift
}

fn main() {
    if PROGRAMS.is_empty() {
        println!("no programs were built (are nasm and clang installed?)");
    }
    for program in PROGRAMS {
        println!("running {}", program.name);
        let (machine, exit) = execute(program);
        println!(
            "    stopped {:?} after {} instructions",
            exit.stop, exit.executed
        );
        for register in machine.cpu.registers() {
            let mut bytes = [0; 16];
            machine
                .cpu
                .read_register(register.id, &mut bytes[..register.size]);
            let value = u128::from_le_bytes(bytes);
            let width = register.size * 2;
            print!("    {:>8} = 0x{value:0width$x}  ", register.name);
            if register.id == RFLAGS {
                println!("{:?}", Flags::from_bits_retain(value as u64));
            } else if signed(value, register.size) < 0 {
                println!("({value}) ({})", signed(value, register.size));
            } else {
                println!("({value})");
            }
        }
        let failures = check(program, &machine, &exit);
        if program.expect.is_empty() {
            println!("    no expectations");
        } else if failures.is_empty() {
            println!("    ok ({} expectations)", program.expect.len());
        } else {
            println!("    FAILED");
            for failure in failures {
                println!("        {failure}");
            }
        }
        println!();
    }
}

// Maps the program at CODE_BASE and a read+write stack below STACK_TOP. The program
// region is also writable and at least 64 KiB, because C programs keep their globals
// (.data/.bss) right after their code.
fn load(code: &[u8]) -> Machine<X86Cpu> {
    let mut machine = Machine::new(X86Cpu::new());
    let code_size = (code.len() as u64).div_ceil(0x1000).max(0x10) * 0x1000;
    machine
        .memory
        .map(CODE_BASE, code_size, Permissions::all())
        .unwrap();
    machine.memory.host_write(CODE_BASE, code).unwrap();
    machine
        .memory
        .map(
            Address(STACK_TOP - STACK_SIZE),
            STACK_SIZE,
            Permissions::READ | Permissions::WRITE,
        )
        .unwrap();
    machine.cpu.write_register(RSP, &STACK_TOP.to_le_bytes());
    machine.cpu.set_pc(CODE_BASE);
    machine
}

fn execute(program: &Program) -> (Machine<X86Cpu>, Exit) {
    let mut machine = load(program.code);
    let exit = run(
        &mut machine,
        &mut Breakpoints::new(),
        Some(INSTRUCTION_LIMIT),
    );
    (machine, exit)
}

// Compares the run against the program's `; expect` lines and returns what didn't match.
// A program without any `; expect` lines isn't checked at all. Otherwise, without an
// `expect stop` line it also has to end at `hlt`.
fn check(program: &Program, machine: &Machine<X86Cpu>, exit: &Exit) -> Vec<String> {
    if program.expect.is_empty() {
        return Vec::new();
    }
    let mut failures = Vec::new();
    let mut stop = "halt";
    for &(name, value) in program.expect {
        match name {
            "stop" => stop = value,
            "executed" => {
                let expected = number(value);
                if u128::from(exit.executed) != expected {
                    failures.push(format!(
                        "executed: expected {expected}, got {}",
                        exit.executed
                    ));
                }
            }
            name => match register(machine, name) {
                Some(actual) if actual == number(value) => {}
                Some(actual) => failures.push(format!(
                    "{name}: expected {:#x}, got {actual:#x}",
                    number(value)
                )),
                None => failures.push(format!("{name}: no such register")),
            },
        }
    }
    if stop_name(exit.stop) != stop {
        failures.push(format!("stop: expected {stop}, got {:?}", exit.stop));
    }
    failures
}

fn register(machine: &Machine<X86Cpu>, name: &str) -> Option<u128> {
    let register = machine
        .cpu
        .registers()
        .iter()
        .find(|register| register.name.eq_ignore_ascii_case(name))?;
    let mut bytes = [0; 16];
    machine
        .cpu
        .read_register(register.id, &mut bytes[..register.size]);
    Some(u128::from_le_bytes(bytes))
}

// Decimal or 0x-prefixed hex, with optional `_` separators.
fn number(value: &str) -> u128 {
    let value = value.replace('_', "");
    let parsed = match value.strip_prefix("0x") {
        Some(hex) => u128::from_str_radix(hex, 16),
        None => value.parse(),
    };
    parsed.unwrap_or_else(|_| panic!("bad number in expect line: {value}"))
}

fn stop_name(stop: Stop) -> String {
    match stop {
        Stop::Cpu(CpuError::Halt) => "halt".to_string(),
        Stop::Cpu(CpuError::Fault(_)) => "fault".to_string(),
        Stop::Cpu(CpuError::IllegalInstruction(_)) => "illegal".to_string(),
        Stop::Cpu(CpuError::Unimplemented(_)) => "unimplemented".to_string(),
        Stop::Breakpoint(_) => "breakpoint".to_string(),
        Stop::InstructionLimit => "limit".to_string(),
    }
}

#[cfg(test)]
fn assert_program(program: &Program) {
    let (machine, exit) = execute(program);
    let failures = check(program, &machine, &exit);
    assert!(
        failures.is_empty(),
        "{}:\n    {}",
        program.name,
        failures.join("\n    ")
    );
}
